const IMAGES_PATH = 'https://f005.backblazeb2.com/file/novelai-images/stories/';

// Theme management
const THEME_KEY = 'story_site_theme_v1';

document.addEventListener('DOMContentLoaded', function() {
    // Theme setup
    const themeToggleBtn = document.getElementById('theme-toggle');
    const bodyEl = document.body;
    
    function applyTheme(theme) {
        if (theme === 'dark') {
            bodyEl.classList.add('dark-mode');
            if (themeToggleBtn) themeToggleBtn.textContent = '☀️';
        } else {
            bodyEl.classList.remove('dark-mode');
            if (themeToggleBtn) themeToggleBtn.textContent = '🌙';
        }
    }
    
    let savedTheme = localStorage.getItem(THEME_KEY) || 'dark';
    applyTheme(savedTheme);
    
    if (themeToggleBtn) {
        themeToggleBtn.addEventListener('click', () => {
            const newTheme = bodyEl.classList.contains('dark-mode') ? 'light' : 'dark';
            localStorage.setItem(THEME_KEY, newTheme);
            applyTheme(newTheme);
        });
    }
    
    // Story gallery setup
    let currentStoryIndex = -1;
    const storyGrid = document.getElementById('story-grid');
    const storyViewer = document.getElementById('story-viewer');
    const storyContent = document.getElementById('story-content');
    const backToGridBtn = document.getElementById('back-to-grid');
    const prevStoryBtn = document.getElementById('prev-story');
    const nextStoryBtn = document.getElementById('next-story');
    const storyCounter = document.getElementById('story-counter');
    
    // Initialize story grid
    function initializeStoryGrid() {
        storyGrid.innerHTML = '';
        
        storiesData.forEach((story, index) => {
            const storyCard = document.createElement('div');
            storyCard.className = 'story-card';
            
            const fullTitle = story.story_plan || `Story ${index + 1}`;
            const displayTitle = fullTitle.length > 200 ? fullTitle.substring(0, 200) + '...' : fullTitle;

            storyCard.innerHTML = `
                <div class="story-image-container">
                    <img src="${IMAGES_PATH}${story.first_image}" alt="${displayTitle.replace(/"/g, '&quot;')}" loading="lazy">
                </div>
                <div class="story-info">
                    <h3 class="story-tile-title" title="${fullTitle.replace(/"/g, '&quot;')}">${displayTitle}</h3>
                    <p>${story.total_images} images</p>
                </div>
            `;
            
            storyCard.addEventListener('click', () => {
                openStory(index);
            });
            
            storyGrid.appendChild(storyCard);
        });
    }
    
    // Open story viewer
    function openStory(storyIndex) {
        currentStoryIndex = storyIndex;
        const story = storiesData[storyIndex];
        
        storyGrid.style.display = 'none';
        storyViewer.style.display = 'block';
        
        // Update counter
        storyCounter.textContent = `Story ${storyIndex + 1} of ${storiesData.length}`;
        
        // Update navigation buttons
        prevStoryBtn.disabled = storyIndex === 0;
        nextStoryBtn.disabled = storyIndex === storiesData.length - 1;
        
        // Populate story content
        storyContent.innerHTML = '';
        storyContent.scrollTop = 0;
        
        story.images.forEach((image, imgIndex) => {
            const storyRow = document.createElement('div');
            storyRow.className = 'story-row';
            
            const img = document.createElement('img');
            img.src = IMAGES_PATH + image.filename;
            img.alt = `Story ${storyIndex + 1}, Image ${imgIndex + 1}`;
            img.loading = 'lazy';
            img.className = 'story-image';
            
            const promptContainer = document.createElement('div');
            promptContainer.className = 'image-prompt';
            
            let promptHTML = `<h4>Image ${imgIndex + 1}</h4>`;
            
            if (image.prompt) {
                promptHTML += `
                    <div class="prompt-section">
                        <h5>Scene Prompt:</h5>
                        <p>${image.prompt}</p>
                    </div>
                `;
            }
            
            // Add character prompts dynamically
            for (let i = 1; i <= 6; i++) {
                const charKey = `character${i}`;
                if (image[charKey]) {
                    promptHTML += `
                        <div class="prompt-section">
                            <h5>Character ${i}:</h5>
                            <p>${image[charKey]}</p>
                        </div>
                    `;
                }
            }
            
            promptHTML += `
                <div class="download-section">
                    <button class="download-btn" data-href="${IMAGES_PATH}${image.filename}" data-filename="${image.filename}">
                        Download Raw Image
                    </button>
                </div>
            `;
            
            promptContainer.innerHTML = promptHTML;
            
            storyRow.appendChild(img);
            storyRow.appendChild(promptContainer);
            storyContent.appendChild(storyRow);
        });
    }
    
    // Close story viewer
    function closeStoryViewer() {
        storyViewer.style.display = 'none';
        storyGrid.style.display = 'grid';
        currentStoryIndex = -1;
        storyContent.scrollTop = 0;
    }
    
    // Navigation handlers
    if (backToGridBtn) {
        backToGridBtn.addEventListener('click', closeStoryViewer);
    }
    
    // Download button handler (using event delegation)
    if (storyContent) {
        storyContent.addEventListener('click', function(e) {
            if (e.target && e.target.classList.contains('download-btn')) {
                const button = e.target;
                const fileUrl = button.dataset.href;
                const fileName = button.dataset.filename;

                button.textContent = 'Downloading...';
                button.disabled = true;

                fetch(fileUrl)
                    .then(response => {
                        if (!response.ok) throw new Error(`Network response was not ok: ${response.statusText}`);
                        return response.blob();
                    })
                    .then(blob => {
                        const url = window.URL.createObjectURL(blob);
                        const a = document.createElement('a');
                        a.style.display = 'none';
                        a.href = url;
                        a.download = fileName;
                        document.body.appendChild(a);
                        a.click();
                        window.URL.revokeObjectURL(url);
                        document.body.removeChild(a);
                        
                        button.textContent = 'Download Raw Image';
                        button.disabled = false;
                    })
                    .catch(err => {
                        console.error('Download failed:', err);
                        alert('Failed to download image. Check the console for details.');
                        button.textContent = 'Download Failed';
                        setTimeout(() => { // Reset button after a delay
                           button.textContent = 'Download Raw Image';
                           button.disabled = false;
                        }, 3000);
                    });
            }
        });
    }

    if (prevStoryBtn) {
        prevStoryBtn.addEventListener('click', () => {
            if (currentStoryIndex > 0) {
                openStory(currentStoryIndex - 1);
            }
        });
    }
    
    if (nextStoryBtn) {
        nextStoryBtn.addEventListener('click', () => {
            if (currentStoryIndex < storiesData.length - 1) {
                openStory(currentStoryIndex + 1);
            }
        });
    }
    
    // Keyboard navigation
    document.addEventListener('keydown', (e) => {
        if (storyViewer && storyViewer.style.display === 'block') {
            if (e.key === 'Escape') {
                closeStoryViewer();
            } else if (e.key === 'ArrowLeft' && prevStoryBtn && !prevStoryBtn.disabled) {
                openStory(currentStoryIndex - 1);
            } else if (e.key === 'ArrowRight' && nextStoryBtn && !nextStoryBtn.disabled) {
                openStory(currentStoryIndex + 1);
            }
        }
    });
    
    // Initialize the app
    initializeStoryGrid();
});
